use serde::{Deserialize,Serialize};use std::collections::BTreeMap;use thiserror::Error;
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct FeatureValue{pub feature_id:String,pub value:Option<f64>,pub event_time_end_ns:i64,pub as_known_at_ns:i64,pub quality_score_ppm:u32,pub lineage_hash:String}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct EventLabel{pub event_kind:String,pub origin_time_ns:i64,pub horizon_seconds:u64,pub occurred:bool,pub outcome_as_known_at_ns:i64,pub label_definition_id:String,pub source_range_hash:String}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct DatasetRow{pub asset:String,pub origin_time_ns:i64,pub as_known_at_ns:i64,pub features:BTreeMap<String,Option<f64>>,pub labels:Vec<EventLabel>,pub quality_score_ppm:u32}
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]pub struct Fold{pub train_start_ns:i64,pub train_end_ns:i64,pub calibration_end_ns:i64,pub test_end_ns:i64,pub embargo_ns:i64}
impl Fold{pub fn validate(self)->Result<Self,DatasetError>{if self.train_start_ns<self.train_end_ns&&self.train_end_ns<self.calibration_end_ns&&self.calibration_end_ns<self.test_end_ns&&self.embargo_ns>=0{Ok(self)}else{Err(DatasetError::Fold)}}pub fn train_contains(self,origin:i64,label_end:i64)->bool{origin>=self.train_start_ns&&label_end<=self.train_end_ns.saturating_sub(self.embargo_ns)}pub fn test_contains(self,origin:i64)->bool{origin>self.calibration_end_ns.saturating_add(self.embargo_ns)&&origin<=self.test_end_ns}}
pub fn join_point_in_time(asset:&str,origin_ns:i64,features:&[FeatureValue],labels:&[EventLabel],quality:u32)->Result<DatasetRow,DatasetError>{if asset.is_empty()||quality>1_000_000{return Err(DatasetError::Row)}let mut map=BTreeMap::new();for f in features{if f.feature_id.is_empty()||f.as_known_at_ns>origin_ns||f.event_time_end_ns>origin_ns||f.quality_score_ppm>1_000_000||f.lineage_hash.len()!=64{return Err(DatasetError::Leakage(f.feature_id.clone()))}if map.insert(f.feature_id.clone(),f.value).is_some(){return Err(DatasetError::Duplicate)}}if labels.iter().any(|l|l.origin_time_ns!=origin_ns||l.outcome_as_known_at_ns<origin_ns){return Err(DatasetError::Row)}Ok(DatasetRow{asset:asset.into(),origin_time_ns:origin_ns,as_known_at_ns:origin_ns,features:map,labels:labels.to_vec(),quality_score_ppm:quality})}
#[derive(Debug,Error)]pub enum DatasetError{#[error("invalid fold")]Fold,#[error("invalid row")]Row,#[error("point-in-time leakage: {0}")]Leakage(String),#[error("duplicate feature")]Duplicate}
